POST_APPROACH_SOURCE = '''
paired_type = pairs[demo_id].get('sorting_paired_type')
if paired_type is not None:
    obj = dict(obj, sorting_paired_type=paired_type,
               sorting_paired_type_evidence=pairs[demo_id]['sorting_paired_type_evidence'])
if paired_type == 'car':
    paired_prior_timing = dict(contact=contact_duration, lift=pickup_lift_duration,
                              close=close_duration, settle=close_settle_duration)
    solid_toy = False
    green_watch = False
    dark_loop = False
    neutral_watch = False
    pinch_height = .021
    position[2] = ctx.table_z + .021
    approach = position + [0., 0., lift_height]
    ctx.sorting_heavy_grasp = bool(compact_gold_vehicle(pairs[demo_id]))
    contact_duration = 12 if ctx.sorting_heavy_grasp else 8
    pickup_lift_duration = 18 if ctx.sorting_heavy_grasp else 8
    close_duration = 10 if ctx.sorting_heavy_grasp else 8
    close_settle_duration = 6 if ctx.sorting_heavy_grasp else 4
    memory.pickups[-1].update(pinch=position.copy(), sorting_paired_type='car')
    memory.source_updates[-1]['paired_car_semantics'] = dict(
        paired_type='car', pinch_height_m=.021,
        retained_gold_timing=bool(ctx.sorting_heavy_grasp),
        previous_timing=paired_prior_timing,
        contact_frames=contact_duration, lift_frames=pickup_lift_duration,
        close_frames=close_duration, settle_frames=close_settle_duration,
        geometry_xy_changed=False, holding_asserted=False)
'''


def _clone(function, bindings):
    """Keep every formal binding except this extension's explicit private replacements."""
    namespace = dict(function.__globals__, **bindings)
    result = FunctionType(function.__code__, namespace, function.__name__,
                          function.__defaults__, function.__closure__)
    result.__kwdefaults__ = function.__kwdefaults__
    return result


def classify_joint(source, demonstration):
    """Use one fixed nearest joint prototype without an acceptance threshold."""
    vector = np.asarray(source, np.float64) + np.asarray(demonstration, np.float64)
    vector /= np.linalg.norm(vector)
    similarities = np.einsum('ij,j->i', PROTOTYPES, vector)
    chosen = int(np.argmax(similarities))
    scores = {label: float(max(value for value, kind in zip(similarities, PROTOTYPE_LABELS)
                              if kind == label)) for label in sorted(set(PROTOTYPE_LABELS))}
    ordered = sorted(scores, key=scores.get, reverse=True)
    return PROTOTYPE_LABELS[chosen], dict(
        method='fixed_normal_paired_four_rotation_cls_nearest_prototype',
        prototype_index=chosen, prototype_origin=PROTOTYPE_ORIGINS[chosen],
        cosine=float(similarities[chosen]), margin_over_next_type=float(scores[ordered[0]]-scores[ordered[1]]),
        class_max_cosines=scores, prototype_data_sha256=PROTOTYPE_DATA_SHA256,
        model_revision=MODEL_REVISION, source_demo_pairing_changed=False)


def prepare_core(raw):
    """Place the last car-only semantic block before the formal parent's AST stack."""
    tree = ast.parse(textwrap.dedent(inspect.getsource(raw)))
    extension = ast.parse(POST_APPROACH_SOURCE).body
    inserted = 0

    class Insert(ast.NodeTransformer):
        """Retain the original source approach and insert no additional action."""
        def visit_For(self, node):
            nonlocal inserted
            self.generic_visit(node)
            output = []
            for statement in node.body:
                output.append(statement)
                if (isinstance(statement, ast.Expr) and isinstance(statement.value, ast.YieldFrom)
                        and isinstance(statement.value.value, ast.Call)
                        and isinstance(statement.value.value.func, ast.Name)
                        and statement.value.value.func.id == 'move'
                        and any(keyword.arg == 'empty_approach' and isinstance(keyword.value, ast.Constant)
                                and keyword.value.value is True for keyword in statement.value.value.keywords)
                        and any(isinstance(arg, ast.Name) and arg.id == 'approach'
                                for arg in statement.value.value.args)):
                    output.extend(deepcopy(extension))
                    inserted += 1
            node.body = output
            return node

    Insert().visit(tree)
    if inserted != 1:
        raise ValueError('Expected the retained single source empty approach')
    rendered = ast.unparse(ast.fix_missing_locations(tree)) + '\n'
    digest = hashlib.sha256(rendered.encode()).hexdigest()[:16]
    filename = str(Path(__file__).with_name('_sorting_paired_car_' + digest + '.py'))
    linecache.cache[filename] = (len(rendered), None, rendered.splitlines(True), filename)
    namespace = dict(raw.__globals__)
    exec(compile(rendered, filename, 'exec'), namespace)
    result = namespace[raw.__name__]
    result.__defaults__ = raw.__defaults__
    result.__kwdefaults__ = raw.__kwdefaults__
    return result


def finish_core(ctx, actual_parent_core):
    """Preserve the actual parent, call its pair closure first, and label only its pairs."""
    core = actual_parent_core
    namespace = dict(core.__globals__)
    original_pair = namespace['pair_objects']
    original_pale = namespace['compact_pale_car']

    def paired(images, targets, demonstrations, demonstration_image=None, return_evidence=False):
        result = original_pair(images, targets, demonstrations, demonstration_image, return_evidence)
        pairs = result[0] if return_evidence else result
        demo_images = images if demonstration_image is None else demonstration_image
        crops = [memory_helpers.crop_of(*memory_helpers.measured_view(images, obj)) for obj in targets]
        crops += [memory_helpers.crop_of(*memory_helpers.measured_view(demo_images, obj))
                  for obj in demonstrations]
        features = _encode(crops)
        source_indices = {id(obj): index for index, obj in enumerate(targets)}
        summary = []
        for demo_id, source in pairs.items():
            source_id = source_indices[id(source)]
            label, evidence = classify_joint(features[source_id], features[len(targets)+int(demo_id)])
            source['sorting_paired_type'] = label
            source['sorting_paired_type_evidence'] = evidence
            summary.append(dict(source_id=source_id, demonstration_id=int(demo_id),
                                paired_type=label, cosine=evidence['cosine'],
                                prototype_index=evidence['prototype_index']))
        if return_evidence:
            result[1]['paired_type_semantics'] = dict(assignments=summary,
                source_demo_pairing_changed=False, only_car_semantics_controlled=True)
        return result

    def compact_pale_car(obj):
        label = obj.get('sorting_paired_type')
        return False if label is not None and label != 'car' else original_pale(obj)

    def constrain_car_apply(original):
        """Keep each existing observation but cancel its car application for noncars."""
        def observed(robot, obj):
            result = original(robot, obj)
            updates = getattr(robot.memory, 'source_updates', [])
            source = (getattr(robot, 'sorting_sources', {}).get(updates[-1].get('demonstration_id'))
                      if updates else None)
            label = source.get('sorting_paired_type') if source is not None else obj.get('sorting_paired_type')
            if result is not None and label is not None and label != 'car':
                result = dict(result, apply=False, paired_type=label,
                              apply_before_paired_type=bool(result.get('apply', False)))
            return result
        return observed

    namespace.update(pair_objects=paired, compact_pale_car=compact_pale_car)
    for name in ('current_car_priority', 'current_car_body_fallback'):
        if name in namespace:
            namespace[name] = constrain_car_apply(namespace[name])
    return _clone(core, namespace)
